create or replace function powerhouse_ops.claim(p_limit integer default 10) returns setof powerhouse_ops.recovery_queue language plpgsql security invoker set search_path=pg_catalog,powerhouse_ops as $f$ begin return query with chosen as (select id from powerhouse_ops.recovery_queue where ((status in ('pending','failed') and next_attempt_at<=now()) or (status='running' and locked_until<now())) and attempts<max_attempts order by next_attempt_at,id limit least(greatest(p_limit,1),100) for update skip locked) update powerhouse_ops.recovery_queue q set status='running',attempts=q.attempts+1,locked_until=now()+interval '5 minutes' from chosen where q.id=chosen.id returning q.*; end $f$; revoke all on function powerhouse_ops.claim(integer) from public,anon,authenticated;
